using System;

namespace Bodu.Extensions;

public partial class DateOnlyExtensionsTests
{

    /// <summary>
    /// Verifies that <see cref="DateOnlyExtensions.LastDateOfWeekInMonth" />, when Called, returns the expected value.
    /// </summary>
    [TestMethod]
    [DynamicData(nameof(DateTimeExtensionsTests.LastDateOfWeekInMonthTestData), typeof(DateTimeExtensionsTests))]
    public void LastDateOfWeekInMonth_WhenCalled_ShouldReturnExpectedDate(DateTime inputDateTime, DayOfWeek dayOfWeek, DateTime expectedDateTime)
    {
        var input = DateOnly.FromDateTime(inputDateTime);
        var expected = DateOnly.FromDateTime(expectedDateTime);

        var actual = input.LastDateOfWeekInMonth(dayOfWeek);

        Assert.AreEqual(expected, actual);
    }

    /// <summary>
    /// Verifies that <see cref="DateOnlyExtensions.LastDateOfWeekInMonth" />, when InvalidDayOfWeek, throws <see cref="ArgumentOutOfRangeException" />.
    /// </summary>
    [TestMethod]
    public void LastDateOfWeekInMonth_WhenInvalidDayOfWeek_ShouldThrowExactly()
    {
        var input = new DateOnly(2024, 4, 1);
        var invalidDay = (DayOfWeek)999;

        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() =>
        {
            _ = input.LastDateOfWeekInMonth(invalidDay);
        });
    }

    /// <summary>
    /// Verifies that <see cref="DateOnlyExtensions.LastDateOfWeekInMonth" />, when MaxValue, returns <see langword="true" />.
    /// </summary>
    [TestMethod]
    public void LastDateOfWeekInMonth_WhenMaxValue_ShouldReturnValidResult()
    {
        var actual = DateOnly.MaxValue.LastDateOfWeekInMonth(DayOfWeek.Friday);

        Assert.IsTrue(actual <= DateOnly.MaxValue);
    }

    /// <summary>
    /// Verifies that <see cref="DateOnlyExtensions.LastDateOfWeekInMonth" />, when MinValue, returns <see langword="true" />.
    /// </summary>
    [TestMethod]
    public void LastDateOfWeekInMonth_WhenMinValue_ShouldReturnValidResult()
    {
        var actual = DateOnly.MinValue.LastDateOfWeekInMonth(DayOfWeek.Monday);

        Assert.IsTrue(actual >= DateOnly.MinValue && actual <= DateOnly.MinValue.AddMonths(1).AddDays(-1));
    }

    // =========================================================================
